71	    /// <summary>API falsa: responde según la pregunta y, si hay ruta, añade una línea de auditoría por petición.</summary>
72	    sealed class ApiFalsa : IDisposable
73	    {
74	        readonly HttpListener _l = new();
75	        public string Url { get; }
76	
77	        public ApiFalsa(Func<string, Fila> segun, string? rutaAuditoria)
78	        {
79	            Url = $"http://localhost:{PuertoLibre()}";
80	            _l.Prefixes.Add(Url + "/");
81	            _l.Start();
82	            _ = Task.Run(async () =>
83	            {
84	                while (_l.IsListening)
85	                {
86	                    HttpListenerContext ctx;
87	                    try { ctx = await _l.GetContextAsync(); } catch { break; }
88	                    string cuerpoPeticion;
89	                    using (var sr = new StreamReader(ctx.Request.InputStream, Encoding.UTF8)) cuerpoPeticion = await sr.ReadToEndAsync();
90	                    using var doc = JsonDocument.Parse(cuerpoPeticion);
91	                    var pregunta = doc.RootElement.GetProperty("pregunta").GetString()!;
92	                    var id = doc.RootElement.GetProperty("usuario").GetProperty("id").GetString()!;
93	                    var f = segun(pregunta);
94	
95	                    if (rutaAuditoria != null)
96	                    {
97	                        var linea = JsonSerializer.Serialize(new Dictionary<string, object?>
98	                        {
99	                            ["fechaHora"] = DateTimeOffset.UtcNow.ToString("o"),
100	                            ["rol"] = "estudiante", ["id"] = id, ["pregunta"] = pregunta,
101	                            ["estudiantesConsultados"] = Array.Empty<string>(), ["citas"] = Array.Empty<object>(),
102	                            ["codigo"] = f.Codigo, ["tokens"] = f.Entrada + f.Salida, ["costoUsd"] = f.Costo,
103	                            ["modeloPedido"] = f.Pedido, ["modelosRespondidos"] = f.Modelos,
104	                            ["tokensEntrada"] = f.Entrada, ["tokensSalida"] = f.Salida,
105	                        });
106	                        File.AppendAllText(rutaAuditoria, linea + "\n", new UTF8Encoding(false));
107	                    }
108	
109	                    string cuerpo = f.Codigo == 200
110	                        ? JsonSerializer.Serialize(new
111	                        {
112	                            respuesta = "texto normal", citas = Array.Empty<object>(), usoDatosEstudiante = false,
113	                            tokens = f.Entrada + f.Salida, costoUsd = f.Costo,
114	                        })
115	                        : "{\"error\":\"sin permiso\"}";
116	                    var bytes = Encoding.UTF8.GetBytes(cuerpo);
117	                    ctx.Response.StatusCode = f.Codigo;
118	                    ctx.Response.ContentType = "application/json";
119	                    await ctx.Response.OutputStream.WriteAsync(bytes);
120	                    ctx.Response.Close();
121	                }
122	            });
123	        }
