130	    async Task<Salida> Ejecutar(string data, string cwd, string url, string? auditoria)
131	    {
132	        var dll = Path.Combine(AppContext.BaseDirectory, "TutorFlow.Evals.dll");
133	        Assert.True(File.Exists(dll), "No esta TutorFlow.Evals.dll junto a las pruebas");
134	        var psi = new ProcessStartInfo("dotnet", $"\"{dll}\"")
135	        {
136	            WorkingDirectory = cwd, RedirectStandardOutput = true, RedirectStandardError = true, UseShellExecute = false,
137	        };
138	        psi.Environment["EVALS_DATA"] = data;
139	        psi.Environment["EVALS_API_URL"] = url;
140	        psi.Environment["EVALS_PAUSA_MS"] = "0";
141	        psi.Environment["EVALS_ESPERA_MS"] = "1";
142	        psi.Environment["LLM_API_KEY"] = "llave-falsa-123";
143	        psi.Environment.Remove("LLM_MODEL");
144	        psi.Environment.Remove("EVALS_AUDITORIA");
145	        if (auditoria != null) psi.Environment["EVALS_AUDITORIA"] = auditoria;
146	        using var p = Process.Start(psi)!;
147	        var o = p.StandardOutput.ReadToEndAsync();
148	        var e = p.StandardError.ReadToEndAsync();
149	        using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(90));
150	        try { await p.WaitForExitAsync(cts.Token); }
151	        catch (OperationCanceledException) { try { p.Kill(true); } catch { } throw; }
152	        var texto = await o + "\n" + await e;
153	        var ruta = Path.Combine(cwd, "evals", "resultados", "ultimo.json");
154	        Assert.True(File.Exists(ruta), "El runner no escribio ultimo.json en el directorio de trabajo. Salida:\n" + texto);
155	        return new Salida(p.ExitCode, texto, JsonDocument.Parse(File.ReadAllText(ruta)).RootElement.Clone());
156	    }
