158	    static JsonElement Caso(Salida s, string id) =>
159	        s.Json.GetProperty("casos").EnumerateArray().Single(c => c.GetProperty("id").GetString() == id);
160	
161	    static string[] Modelos(JsonElement c) =>
162	        c.GetProperty("modelosRespondidos").EnumerateArray().Select(x => x.GetString()!).ToArray();
163	
164	    // Tres preguntas: A y B responden 200; B con un modelo distinto al pedido; C termina en 403 sin llamar al modelo.
165	    static Fila Guion(string pregunta) => pregunta switch
166	    {
167	        "pregunta-a" => new Fila(200, 100, 20, 0.001, Pedido, [Pedido]),
168	        "pregunta-b" => new Fila(200, 300, 40, 0.003, Pedido, ["gemini-3.6-flash"]),
169	        _ => new Fila(403, 0, 0, 0, null, []),
170	    };
