176	    [Fact]
177	    public async Task EvalsModelo_cada_pregunta_trae_modelo_pedido_respondidos_tokens_y_costo()
178	    {
179	        var (data, cwd) = Escenario(TresCasos());
180	        var aud = Path.Combine(NuevoDir(), "auditoria.jsonl");
181	        using var api = new ApiFalsa(Guion, aud);
182	
183	        var s = await Ejecutar(data, cwd, api.Url, aud);
184	
185	        var a = Caso(s, "E-A");
186	        Assert.Equal(Pedido, a.GetProperty("modeloPedido").GetString());
187	        Assert.Equal([Pedido], Modelos(a));
188	        Assert.Equal(100, a.GetProperty("tokensEntrada").GetInt64());
189	        Assert.Equal(20, a.GetProperty("tokensSalida").GetInt64());
190	        Assert.Equal(0.001, a.GetProperty("costoUsd").GetDouble(), 9);
191	
192	        var b = Caso(s, "E-B");
193	        Assert.Equal([ "gemini-3.6-flash" ], Modelos(b));
194	        Assert.Equal(300, b.GetProperty("tokensEntrada").GetInt64());
195	        Assert.Equal(40, b.GetProperty("tokensSalida").GetInt64());
196	        Assert.Equal(0.003, b.GetProperty("costoUsd").GetDouble(), 9);
197	
198	        var c = Caso(s, "E-C");
199	        Assert.Equal(JsonValueKind.Null, c.GetProperty("modeloPedido").ValueKind);
200	        Assert.Empty(Modelos(c));
201	        Assert.Equal(0, c.GetProperty("tokensEntrada").GetInt64());
202	        Assert.Equal(0, c.GetProperty("tokensSalida").GetInt64());
203	    }
