247	
248	    [Fact]
249	    public async Task EvalsModelo_auditoria_ausente_modelo_desconocido_advertencia_y_mismo_codigo_de_salida()
250	    {
251	        var (data, cwd) = Escenario(TresCasos());
252	        var audReal = Path.Combine(NuevoDir(), "auditoria.jsonl");
253	        using var conAud = new ApiFalsa(Guion, audReal);
254	        var base1 = await Ejecutar(data, cwd, conAud.Url, audReal);
255	
256	        var (data2, cwd2) = Escenario(TresCasos());
257	        var audNoExiste = Path.Combine(NuevoDir(), "no-existe.jsonl");
258	        using var sinAud = new ApiFalsa(Guion, null);
259	        var s = await Ejecutar(data2, cwd2, sinAud.Url, audNoExiste);
260	
261	        Assert.False(File.Exists(audNoExiste));
262	        Assert.Equal(base1.Codigo, s.Codigo);
263	        Assert.Contains("desconocido", s.Texto);
264	        Assert.Contains("ADVERTENCIA", s.Texto);
265	        foreach (var id in new[] { "E-A", "E-B", "E-C" })
266	        {
267	            var c = Caso(s, id);
268	            Assert.True(c.TryGetProperty("advertencia", out var adv) && adv.ValueKind == JsonValueKind.String);
269	            Assert.Empty(Modelos(c));
270	            Assert.False(c.GetProperty("modeloDistinto").GetBoolean());
271	        }
272	        Assert.Equal(0, s.Json.GetProperty("modelo").GetProperty("modeloDistinto").GetInt32());
273	        Assert.Equal(3, s.Json.GetProperty("modelo").GetProperty("sinAuditoria").GetInt32());
274	    }
