276	    // ---------- Resumen de uso ----------
277	
278	    [Fact]
279	    public async Task EvalsModelo_resumen_separa_las_403_del_resto_con_tokens_promedio_costo_total_y_por_1000()
280	    {
281	        var (data, cwd) = Escenario(TresCasos());
282	        var aud = Path.Combine(NuevoDir(), "auditoria.jsonl");
283	        using var api = new ApiFalsa(Guion, aud);
284	        var s = await Ejecutar(data, cwd, api.Url, aud);
285	        var m = s.Json.GetProperty("modelo");
286	
287	        var r403 = m.GetProperty("rechazadas403");
288	        Assert.Equal(1, r403.GetProperty("preguntas").GetInt32());
289	        Assert.Equal(0, r403.GetProperty("tokens").GetInt64());
290	        Assert.Equal(0, r403.GetProperty("costoTotalUsd").GetDouble());
291	        Assert.Equal(0, r403.GetProperty("costoPor1000Usd").GetDouble());
292	
293	        var resto = m.GetProperty("resto");
294	        Assert.Equal(2, resto.GetProperty("preguntas").GetInt32());
295	        Assert.Equal(400, resto.GetProperty("tokensEntrada").GetInt64());
296	        Assert.Equal(60, resto.GetProperty("tokensSalida").GetInt64());
297	        Assert.Equal(460, resto.GetProperty("tokens").GetInt64());
298	        Assert.Equal(230, resto.GetProperty("tokensPromedio").GetDouble(), 6);
299	        Assert.Equal(0.004, resto.GetProperty("costoTotalUsd").GetDouble(), 9);
300	        Assert.Equal(2.0, resto.GetProperty("costoPor1000Usd").GetDouble(), 6);   // 0.004 / 2 * 1000
301	
302	        // La salida legible lo repite.
303	        Assert.Contains("403", s.Texto);
304	        Assert.Contains("promedio", s.Texto, StringComparison.OrdinalIgnoreCase);
305	        Assert.Contains("1.000", s.Texto);
306	        Assert.Contains(0.004.ToString("F6", CultureInfo.CurrentCulture), s.Texto);
307	    }
