309	    [Fact]
310	    public async Task EvalsModelo_la_corrida_no_deja_ultimo_json_en_el_repositorio()
311	    {
312	        var real = Path.Combine(SubirA("TutorFlow.sln"), "evals", "resultados", "ultimo.json");
313	        var antes = File.Exists(real) ? File.GetLastWriteTimeUtc(real) : (DateTime?)null;
314	        var (data, cwd) = Escenario(Caso("E-A", "pregunta-a"));
315	        var aud = Path.Combine(NuevoDir(), "auditoria.jsonl");
316	        using var api = new ApiFalsa(Guion, aud);
317	        await Ejecutar(data, cwd, api.Url, aud);
318	        var despues = File.Exists(real) ? File.GetLastWriteTimeUtc(real) : (DateTime?)null;
319	        Assert.Equal(antes, despues);
320	    }
321	
322	    static string SubirA(string archivo)
323	    {
324	        for (var d = new DirectoryInfo(AppContext.BaseDirectory); d != null; d = d.Parent)
325	            if (File.Exists(Path.Combine(d.FullName, archivo))) return d.FullName;
326	        throw new InvalidOperationException("No se encontro " + archivo);
327	    }
328	}
