26	    {
27	        foreach (var d in _dirs) { try { Directory.Delete(d, true); } catch { } }
28	    }
29	
30	    string NuevoDir()
31	    {
32	        var d = Path.Combine(Path.GetTempPath(), "tf-evmod-" + Guid.NewGuid().ToString("N"));
33	        Directory.CreateDirectory(d);
