147	        Assert.Equal(JsonValueKind.String, l.GetProperty("fechaHora").ValueKind);
148	        var f = DateTimeOffset.Parse(l.GetProperty("fechaHora").GetString()!, System.Globalization.CultureInfo.InvariantCulture);
149	        Assert.Equal(TimeSpan.Zero, f.Offset);
150	        Assert.InRange((DateTimeOffset.UtcNow - f).TotalSeconds, -5, 120);
151	
152	        foreach (var c in new[] { "rol", "id", "pregunta" })
153	            Assert.True(l.GetProperty(c).ValueKind is JsonValueKind.String or JsonValueKind.Null, c + " debe ser texto o null");
154	
155	        var est = l.GetProperty("estudiantesConsultados");
156	        Assert.Equal(JsonValueKind.Array, est.ValueKind);
157	        var ids = est.EnumerateArray().Select(e => { Assert.Equal(JsonValueKind.String, e.ValueKind); return e.GetString()!; }).ToList();
158	        Assert.Equal(ids.Count, ids.Distinct().Count());
159	
160	        var citas = l.GetProperty("citas");
161	        Assert.Equal(JsonValueKind.Array, citas.ValueKind);
162	        foreach (var c in citas.EnumerateArray())
163	        {
164	            Assert.Equal(JsonValueKind.Object, c.ValueKind);
165	            Assert.Equal(JsonValueKind.String, c.GetProperty("documento").ValueKind);
166	            Assert.Equal(JsonValueKind.String, c.GetProperty("seccion").ValueKind);
167	        }
168	
169	        Assert.Equal(JsonValueKind.Number, l.GetProperty("codigo").ValueKind);
170	        Assert.True(l.GetProperty("codigo").TryGetInt32(out _));
171	        Assert.Equal(JsonValueKind.Number, l.GetProperty("tokens").ValueKind);
172	        Assert.True(l.GetProperty("tokens").TryGetInt64(out var tk) && tk >= 0);
173	        Assert.Equal(JsonValueKind.Number, l.GetProperty("costoUsd").ValueKind);
174	        Assert.True(l.GetProperty("costoUsd").GetDouble() >= 0);
175	    }
176	
177	    public static string[] Estudiantes(JsonElement l) =>
178	        l.GetProperty("estudiantesConsultados").EnumerateArray().Select(e => e.GetString()!).ToArray();
179	
180	    public static int Codigo(JsonElement l) => l.GetProperty("codigo").GetInt32();
181	    public static long Tokens(JsonElement l) => l.GetProperty("tokens").GetInt64();
182	    public static double Costo(JsonElement l) => l.GetProperty("costoUsd").GetDouble();
183	    public static string? Texto(JsonElement l, string campo) =>
184	        l.GetProperty(campo).ValueKind == JsonValueKind.Null ? null : l.GetProperty(campo).GetString();
