186	    /// <summary>(entrada*pE + salida*pS) / 1e6.</summary>
187	    public static double CostoEsperado(long entrada, long salida, double precioEntrada, double precioSalida) =>
188	        (entrada * precioEntrada + salida * precioSalida) / 1_000_000.0;
189	}
