100	    Console.WriteLine(modeloTxt + (res.ModeloDistinto ? "  MODELO DISTINTO" : ""));
101	}
102	
103	var resumen = Evaluador.Resumir(resultados);
104	var veredicto = resumen.CodigoSalida switch { 0 => "APROBADA", 1 => "REPROBADA", _ => "INCONCLUSA" };
105	Console.WriteLine();
106	Console.WriteLine($"Aprobadas: {resumen.Aprobadas}/{resumen.ConResultado} con resultado ({resumen.Total} casos, {resumen.SinResultado} sin resultado)");
107	Console.WriteLine($"Puntaje: {resumen.Puntaje:P1} (umbral {resumen.Umbral:P0})");
108	Console.WriteLine($"Reglas duras (R1 citas, R2 privacidad/llave): {(resumen.ReglasDurasOk ? "OK" : "VIOLADAS")}");
109	Console.WriteLine($"Tokens: total {resumen.TokensTotales}, promedio {resumen.TokensPromedio:F1} por pregunta");
110	Console.WriteLine($"Costo USD: total {resumen.CostoTotalUsd:F6}, promedio {resumen.CostoPromedioUsd:F6}, estimado por 1.000 preguntas {resumen.CostoPor1000Usd:F4}");
111	Console.WriteLine($"Veredicto: {veredicto}");
112	
113	var um = UsoModelo.Resumir(resultados, Environment.GetEnvironmentVariable("LLM_MODEL"),
114	    Environment.GetEnvironmentVariable("LLM_PRECIO_ENTRADA_MTOK"), Environment.GetEnvironmentVariable("LLM_PRECIO_SALIDA_MTOK"));
115	Console.WriteLine();
116	Console.WriteLine("Modelo y uso (diagnóstico, no afecta el puntaje)");
117	Console.WriteLine($"  Modelo pedido: {um.ModeloPedido ?? "desconocido"}");
118	Console.WriteLine($"  Modelos que respondieron: {(um.ModelosRespondidos.Count == 0 ? "desconocido" : string.Join(", ", um.ModelosRespondidos.Select(k => $"{k.Key} ({k.Value} preguntas)")))}");
119	Console.WriteLine($"  Preguntas: {um.Preguntas} (sin línea de auditoría: {um.SinAuditoria})");
120	Console.WriteLine($"  MODELO DISTINTO: {um.ModeloDistinto} preguntas");
121	Console.WriteLine($"  Precios USD/Mtok: entrada {um.PrecioEntradaMtok}, salida {um.PrecioSalidaMtok}");
122	void Imprimir(string nombre, GrupoUso g) =>
123	    Console.WriteLine($"  {nombre}: {g.Preguntas} preguntas | tokens entrada {g.TokensEntrada}, salida {g.TokensSalida}, total {g.Tokens}, promedio {g.TokensPromedio:F1} | costo total {g.CostoTotalUsd:F6} USD, estimado por 1.000 preguntas {g.CostoPor1000Usd:F4} USD");
124	Imprimir("(a) Terminaron en 403", um.Rechazadas403);
125	if (um.Rechazadas403.ConTokens.Count > 0)
126	    Console.WriteLine($"      ATENCION: 403 con tokens > 0 (403 por herramienta tras llamar al modelo): {string.Join(", ", um.Rechazadas403.ConTokens)}");
127	Imprimir("(b) Resto", um.Resto);
128	
129	Directory.CreateDirectory(Path.Combine(evalsDir, "resultados"));
130	File.WriteAllText(Path.Combine(evalsDir, "resultados", "ultimo.json"),
131	    JsonSerializer.Serialize(new { fecha = DateTime.UtcNow, veredicto, resumen, modelo = um, casos = resultados },
132	        new JsonSerializerOptions { WriteIndented = true, PropertyNamingPolicy = JsonNamingPolicy.CamelCase }));
133	return resumen.CodigoSalida;
