1	using System.Text;
2	using System.Text.Json;
3	
4	namespace TutorFlow.Evals;
5	
6	public sealed record LineaAuditoria(
7	    string? ModeloPedido, List<string> ModelosRespondidos, long TokensEntrada, long TokensSalida,
8	    long Tokens, double CostoUsd, int Codigo);
9	
10	public sealed class GrupoUso
11	{
12	    public int Preguntas { get; set; }
13	    public long TokensEntrada { get; set; }
14	    public long TokensSalida { get; set; }
15	    public long Tokens { get; set; }
16	    public double TokensPromedio { get; set; }
17	    public double CostoTotalUsd { get; set; }
18	    public double CostoPor1000Usd { get; set; }
19	    public List<string> ConTokens { get; set; } = new();
20	}
21	
22	public sealed class ResumenModelo
23	{
24	    public string? ModeloPedido { get; set; }
25	    public Dictionary<string, int> ModelosRespondidos { get; set; } = new();
26	    public int Preguntas { get; set; }
27	    public int SinAuditoria { get; set; }
28	    public int ModeloDistinto { get; set; }
29	    public GrupoUso Rechazadas403 { get; set; } = new();
30	    public GrupoUso Resto { get; set; } = new();
31	    public string PrecioEntradaMtok { get; set; } = "no definidos";
32	    public string PrecioSalidaMtok { get; set; } = "no definidos";
33	}
34	
35	/// <summary>Lectura de la auditoría de la API para saber qué modelo respondió. Solo diagnóstico.</summary>
36	public static class UsoModelo
37	{
38	    public static long Longitud(string ruta)
39	    {
40	        try { return File.Exists(ruta) ? new FileInfo(ruta).Length : 0; }
41	        catch (IOException) { return 0; }
42	    }
43	
44	    public static string QuitarPrefijo(string m) => m.StartsWith("models/", StringComparison.OrdinalIgnoreCase) ? m[7..] : m;
45	
46	    /// <summary>Última línea nueva (desde el byte <paramref name="desde"/>) cuya pregunta e id coinciden.</summary>
47	    public static LineaAuditoria? Buscar(string ruta, long desde, string pregunta, string id)
48	    {
49	        try
50	        {
51	            if (!File.Exists(ruta)) return null;
52	            string texto;
53	            using (var fs = new FileStream(ruta, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete))
54	            {
55	                if (desde > fs.Length) desde = 0; // el archivo se rotó
56	                fs.Seek(desde, SeekOrigin.Begin);
57	                using var sr = new StreamReader(fs, Encoding.UTF8);
58	                texto = sr.ReadToEnd();
59	            }
60	            LineaAuditoria? res = null;
61	            foreach (var l in texto.Split('\n', StringSplitOptions.RemoveEmptyEntries))
62	            {
63	                try
64	                {
65	                    using var d = JsonDocument.Parse(l);
66	                    var r = d.RootElement;
67	                    if (r.ValueKind != JsonValueKind.Object) continue;
68	                    if (Str(r, "pregunta") != pregunta || Str(r, "id") != id) continue;
69	                    var modelos = new List<string>();
70	                    if (r.TryGetProperty("modelosRespondidos", out var mr) && mr.ValueKind == JsonValueKind.Array)
71	                        foreach (var m in mr.EnumerateArray())
72	                            if (m.ValueKind == JsonValueKind.String && m.GetString() is { Length: > 0 } s) modelos.Add(s);
73	                    res = new LineaAuditoria(Str(r, "modeloPedido"), modelos, Num(r, "tokensEntrada"), Num(r, "tokensSalida"),
74	                        Num(r, "tokens"), r.TryGetProperty("costoUsd", out var c) && c.ValueKind == JsonValueKind.Number ? c.GetDouble() : 0,
75	                        (int)Num(r, "codigo"));
76	                }
77	                catch (JsonException) { }
78	            }
79	            return res;
80	        }
81	        catch (IOException) { return null; }
82	        catch (UnauthorizedAccessException) { return null; }
83	    }
84	
85	    static string? Str(JsonElement e, string n) => e.TryGetProperty(n, out var v) && v.ValueKind == JsonValueKind.String ? v.GetString() : null;
86	    static long Num(JsonElement e, string n) => e.TryGetProperty(n, out var v) && v.ValueKind == JsonValueKind.Number && v.TryGetInt64(out var l) ? l : 0;
87	
88	    /// <summary>Completa el resultado con lo que dice la auditoría (o la respuesta 200 para tokens y costo).</summary>
89	    public static void Aplicar(ResultadoCaso r, LineaAuditoria? a)
90	    {
91	        r.AuditoriaEncontrada = a != null;
92	        if (a != null)
93	        {
94	            r.ModeloPedido = a.ModeloPedido;
95	            r.ModelosRespondidos = a.ModelosRespondidos;
96	            r.TokensEntrada = a.TokensEntrada;
97	            r.TokensSalida = a.TokensSalida;
98	        }
99	        else r.Advertencia = "auditoría no disponible: modelo desconocido";
100	
