        e.Proveedor.Ok(CuerpoProveedor(prov,
            "{\"prompt_tokens\":2147483647,\"completion_tokens\":2147483647}",
            "{\"input_tokens\":2147483647,\"output_tokens\":2147483647}"));
        await VerificaTokensCosto(e, int.MaxValue, long.MaxValue);
