    {
        using var e = new EntornoAuditoria(null, Cfg(prov));
        e.Proveedor.Ok(CuerpoProveedor(prov,
            "{\"prompt_tokens\":-5,\"completion_tokens\":-5}",
            "{\"input_tokens\":-5,\"output_tokens\":-5}"));
        await VerificaTokensCosto(e, 0, 0, exacto0: true);
    }

