        File.WriteAllText(ruta, "{\"pregunta\":\"previa\",\"id\":\"X\",\"codigo\":200,\"tokens\":1}\n");
        File.SetLastWriteTimeUtc(ruta, ultimaEscritura);
    }

    async Task<Salida> CorreEnRaiz(string raiz, string rutaQueEscribeLaApi)
    {
        var data = NuevoDir();
