    };

    string[] CasosConSinResultado() => [Caso("E-A", "pregunta-a"), Caso("E-B", "pregunta-b"), Caso("E-C", "pregunta-c")];

    // ---------- (a) Promedios solo sobre las preguntas con respuesta ----------

